use std::sync::{Arc, Mutex};

use jiff::Timestamp;
use serde::Serialize;

use super::run::{Options, Progress, RunError, RunReport};
use super::trigger::Trigger;
use crate::serve::Shared;

#[derive(Debug, Clone, PartialEq, Default, Serialize)]
pub struct Status {
    pub running: Option<Progress>,
    pub last: Option<RunReport>,
}

#[derive(Debug)]
pub struct Runner {
    lock: Arc<tokio::sync::Mutex<()>>,
    status: Arc<Mutex<Status>>,
    trigger: Option<Trigger>,
}

impl Runner {
    pub fn new(trigger: Option<Trigger>) -> Runner {
        Runner {
            lock: Arc::new(tokio::sync::Mutex::new(())),
            status: Arc::new(Mutex::new(Status::default())),
            trigger,
        }
    }

    pub fn trigger(&self) -> Option<Trigger> {
        self.trigger
    }

    pub fn status(&self) -> Status {
        self.status
            .lock()
            .expect("Runner.status: the status lock is not poisoned")
            .clone()
    }

    pub async fn start(
        app: Shared,
        options: &Options,
        now: Timestamp,
    ) -> Result<Progress, RunError> {
        let result: Result<Progress, RunError> = todo!("Runner.start {options:?} {now}");
        debug_assert!(
            result.as_ref().map_or(true, |p| app
                .runner
                .status()
                .running
                .is_some_and(|r| r.run == p.run)),
            "Runner.start: a started run is the running one"
        );
        debug_assert!(
            result.as_ref().map_or(true, |p| p.done == 0),
            "Runner.start: a started run has done nothing yet"
        );
        result
    }

    pub async fn on_ingest(app: Shared, now: Timestamp) -> Option<Result<Progress, RunError>> {
        let no_trigger = app.runner.trigger.is_none();
        let result: Option<Result<Progress, RunError>> = todo!("Runner.on_ingest {now}");
        debug_assert!(
            !no_trigger || result.is_none(),
            "Runner.on_ingest: no trigger, no run"
        );
        debug_assert!(
            !matches!(result, Some(Err(RunError::Busy))),
            "Runner.on_ingest: a busy runner skips, it does not fail"
        );
        result
    }

    pub fn spawn_on_ingest(app: Shared) {
        if app.runner.trigger.is_some() {
            tokio::spawn(async move {
                if let Some(Err(error)) = Runner::on_ingest(app, Timestamp::now()).await {
                    eprintln!("alfred distill: {error}");
                }
            });
        }
    }
}

pub fn summary_line(report: &RunReport) -> String {
    let result: String = todo!("summary_line {report:?}");
    debug_assert!(
        result.contains(&report.run),
        "summary_line: the line names the run"
    );
    result
}

